console.log('--- Case A: server-sent UTC-midnight timestamp for 2019-07-30 ---');
console.log('old result:', unlocal_date_old(new Date(serverMs)).toDateString());
console.log('new result:', unlocal_date_new(new Date(serverMs)).toDateString());

// Case B: client round-trip -- model.value was set to date.toDateString() by _on_select,
// then re-parsed by `new Date(model.value)` on next render. Non-ISO date strings parse as LOCAL midnight.
console.log('--- Case B: client round-trip string "Tue Jul 30 2019" (parses as local midnight) ---');
const clientDate = new Date('Tue Jul 30 2019');
console.log('parsed instant (ISO):', clientDate.toISOString());
console.log('old result:', unlocal_date_old(new Date(clientDate.getTime())).toDateString());
